(()=>{
const original=document.querySelector('.layout>.channel');if(!original)return;const channels=document.createElement('div');channels.className='im-channel-list';original.before(channels);channels.append(original);original.dataset.channel='welink';original.setAttribute('role','button');original.tabIndex=0;original.setAttribute('aria-label','WeLink助手');original.setAttribute('aria-pressed','true');const wx=document.createElement('div');wx.className='channel';wx.dataset.channel='wechat';wx.setAttribute('role','button');wx.tabIndex=0;wx.setAttribute('aria-label','微信助手');wx.setAttribute('aria-pressed','false');wx.innerHTML='<div class="logo wechat-logo"><svg viewBox="0 0 40 40" width="32" height="32" fill="currentColor" aria-hidden="true"><path d="M17 7C9 7 3 12 3 18c0 4 2 7 6 9l-1 5 5-3c1 0 2 1 4 1 1 0 2 0 3-1-3-2-5-5-5-8 0-6 5-10 12-11-3-2-6-3-10-3Zm-5 8a2 2 0 1 1 0 4 2 2 0 0 1 0-4Zm10 0a2 2 0 1 1 0 4 2 2 0 0 1 0-4Z"/><path d="M28 13c-6 0-11 4-11 9s5 9 11 9h3l4 3-1-5c3-1 5-4 5-7 0-5-5-9-11-9Zm-4 6a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3Zm8 0a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3Z"/></svg></div><div><strong>微信助手</strong><span class="badge">未连接</span></div><span class="tick">✓</span>';channels.append(wx);
let channel='welink';const config=document.querySelector('.config'),initial=config.innerHTML;function key(){return channel==='wechat'?'herp-wechat-demo-connected':'herp-im-demo-connected'}
function refreshBadges(){channels.querySelectorAll('.channel').forEach(c=>{const value=localStorage.getItem(c.dataset.channel==='wechat'?'herp-wechat-demo-connected':'herp-im-demo-connected')==='true',badge=c.querySelector('.badge');badge.textContent=value?'已启用 · 演示':'未连接';badge.classList.toggle('connected',value);c.setAttribute('aria-pressed',String(c.dataset.channel===channel))})}
update=function(){document.getElementById('qr').style.display=connected?'none':'block';document.getElementById('success').style.display=connected?'block':'none';refreshBadges()};
connect=function(){connected=true;localStorage.setItem(key(),'true');update()};disconnect=function(){connected=false;localStorage.setItem(key(),'false');document.getElementById('result').textContent='';update()};testConnection=function(){document.getElementById('result').textContent='✓ 演示连接测试完成，可展示任务指令与消息通知；未向真实'+(channel==='wechat'?'微信':'WeLink')+'发送消息。'};
function choose(value){channel=value;config.innerHTML=initial;if(channel==='wechat'){config.innerHTML=config.innerHTML.replaceAll('WeLink','微信').replaceAll('Welink','微信');const image=config.querySelector('.qr img');image.src='assets/wechat-demo-qr.svg';image.alt='微信助手演示二维码';const open=config.querySelector('.actions button:nth-child(2)');open.removeAttribute('onclick');open.onclick=()=>{const d=document.createElement('dialog');d.className='wechat-preview';d.innerHTML='<h2>微信助手</h2><p>✓ 微信助手演示连接已启用</p><div class="wechat-preview-message">你好，小琴。我可以协助查询库存、跟进任务和接收业务通知。</div><p class="wechat-preview-tip">当前为交互演示，未接入真实微信服务。</p><button>关闭</button>';document.body.append(d);d.querySelector('button').onclick=()=>d.remove();d.showModal()}}connected=localStorage.getItem(key())==='true';config.querySelectorAll('[name=mode]').forEach(r=>r.onchange=()=>{document.getElementById('qr-label').textContent='扫码'+(r.value==='new'?'创建新的 ':'授权已有 ')+(channel==='wechat'?'微信':'WeLink')+'助手'});update()}
channels.querySelectorAll('.channel').forEach(c=>{c.onclick=()=>choose(c.dataset.channel);c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(c.dataset.channel)}}});refreshBadges();
})();
